// NOTE: Changelog page using fumadocs-mdx for MDX content management
import { docs } from '@/.source';
import { getMDXComponents } from '@/components/mdx-components';
import { formatDate } from '@/lib/utils';
import { GitFork } from 'lucide-react';
import { GridPattern } from '@/components/ui/grid-pattern';

import type { ComponentType } from 'react';
import type { MDXComponents } from '@/components/mdx-components';

interface ChangelogDoc {
  date: string;
  title: string;
  version?: string;
  tags?: string[];
  body: ComponentType<{ components?: MDXComponents }>;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function isChangelogDoc(value: unknown): value is ChangelogDoc {
  if (!isRecord(value)) return false;

  if (typeof value.date !== 'string') return false;
  if (typeof value.title !== 'string') return false;
  if (typeof value.body !== 'function') return false;

  if (value.version !== undefined && typeof value.version !== 'string') {
    return false;
  }

  if (
    value.tags !== undefined &&
    (!Array.isArray(value.tags) ||
      !value.tags.every((t) => typeof t === 'string'))
  ) {
    return false;
  }

  return true;
}

export default function HomePage() {
  const allPages: unknown[] = Array.isArray(docs) ? (docs as unknown[]) : [];

  const sortedChangelogs = allPages
    .filter(isChangelogDoc)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="bg-black-2 relative min-h-screen overflow-hidden">
      {/* Background Grid Pattern */}
      <GridPattern
        width={60}
        height={60}
        className="absolute inset-0 h-full w-full"
        strokeColor="rgba(255, 255, 255, 0.03)"
      />

      {/* Header */}
      {/* <div className="border-border/50 border-b"> */}
      {/*   <div className="relative mx-auto max-w-5xl"> */}
      {/*     <div className="flex items-center justify-between p-3"> */}
      {/*       <h1 className="text-3xl font-semibold tracking-tight">Changelog</h1> */}
      {/*     </div> */}
      {/*   </div> */}
      {/* </div> */}

      {/* Timeline */}
      <div className="relative mx-auto max-w-5xl rounded-4xl px-6 pt-10 sm:outline-2 lg:px-10">
        <div className="relative">
          {sortedChangelogs.map((changelog, idx) => {
            const MDX = changelog.body;
            const date = new Date(changelog.date);
            const formattedDate = formatDate(date);
            const version = changelog.version;
            const tags = changelog.tags;

            return (
              <div key={idx} className="relative">
                <div className="flex flex-col gap-y-6 md:flex-row">
                  <div className="shrink-0 md:w-48">
                    <div className="pb-10 md:sticky md:top-8">
                      <time className="text-md text-green-1 mb-3 block font-bold">
                        {formattedDate}
                      </time>

                      {version && (
                        <div className="text-foreground outline-green-1 text-md relative z-10 inline-flex h-10 items-center justify-center gap-2 rounded-lg px-4 font-bold outline-2">
                          <span>
                            <GitFork className="size-4" />
                          </span>
                          {version}
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Right side - Content */}
                  <div className="relative flex-1 pb-10 md:pl-8">
                    {/* Vertical timeline line */}
                    <div className="bg-border absolute top-2 left-0 hidden h-full w-px md:block">
                      {/* Timeline dot */}
                      <div className="bg-green-1 absolute z-10 hidden size-3 -translate-x-1/2 rounded-full md:block" />
                    </div>

                    <div className="space-y-6">
                      <div className="relative z-10 flex flex-col gap-2">
                        <h2 className="text-3xl font-semibold tracking-tight text-balance">
                          {changelog.title}
                        </h2>

                        {tags && tags.length > 0 && (
                          <div className="flex flex-wrap gap-2">
                            {/* Tags */}
                            {tags.map((tag) => (
                              <span
                                key={tag}
                                className="bg-muted text-muted-foreground flex h-6 w-fit items-center justify-center rounded-full border px-2 text-xs font-medium"
                              >
                                {tag}
                              </span>
                            ))}
                          </div>
                        )}
                      </div>
                      <div className="prose dark:prose-invert prose-headings:scroll-mt-8 prose-headings:font-semibold prose-a:no-underline prose-headings:tracking-tight prose-headings:text-balance prose-p:tracking-tight prose-p:text-balance max-w-none">
                        <MDX components={getMDXComponents()} />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}
